def transform(grid):
    # overlay left-side binary pattern onto right side by replacing 9s with corresponding values
    out=[r[:] for r in grid]
    # the two halves are 10x12 binary, 10x12 encoded noise; decode based on left pattern? 
    # likely right grid stores sparse marks; map 1s from left mask to 0s? 
    for i in range(len(grid)):
        for j in range(12):
            if grid[i][j]==1:
                out[i][13+j]=0 if out[i][13+j]==9 else out[i][13+j]
    return out
PY

